async function requestPushPermission() {
  if (!messaging) return null;
  try {
    const permission = await Notification.requestPermission();
    if (permission !== "granted") return null;
    const token = await getToken(messaging, { vapidKey: VAPID_KEY });
    return token;
  } catch(e) { return null; }
}

async function savePushToken(memberId, token) {
  if (!token) return;
  await updateDoc(doc(db, "members", String(memberId)), { pushToken: token });
}

// Show a local notification (works when app is open)
function showLocalNotification(title, body) {
  if (Notification.permission === "granted") {
    new Notification(title, { body, icon: "/logo192.png" });
  }
}

// Check birthdays and show notification
function checkBirthdayNotifications(members, shownRef) {
  const now = new Date();
  const today = `${String(now.getMonth()+1).padStart(2,"0")}-${String(now.getDate()).padStart(2,"0")}`;
  for (const m of members) {
    if (!m.birthday) continue;
    const bdMD = m.birthday.slice(5); // "MM-DD"
    const key = `bday-${m.id}-${now.getFullYear()}`;
    if (bdMD === today && !shownRef.current[key]) {
      showLocalNotification("🎂 Tillykke med fødselsdagen!", `${m.name} har fødselsdag i dag!`);
      shownRef.current[key] = true;
      localStorage.setItem(key, "1");
    }
  }
}
function checkAutoNotifications(meetings, shownRef) {
  const now = new Date();
  now.setHours(0,0,0,0);
  for (const m of meetings) {
    if (!isUpcoming(m.date)) continue;
    const meetingDate = new Date(m.date);
    const daysLeft = Math.ceil((meetingDate - now) / 86400000);
    const key7   = `notif-7-${m.id}`;
    const keyToday = `notif-today-${m.id}`;
    const keyDl  = `notif-dl-${m.id}`;

    // 7 days before
    if (daysLeft === 7 && !shownRef.current[key7]) {
      showLocalNotification("RT30X6 – Møde om 7 dage", `${m.title} – ${fmtShort(m.date)} kl. ${m.time}`);
      shownRef.current[key7] = true;
      localStorage.setItem(key7, "1");
    }
    // Day of meeting
    if (daysLeft === 0 && !shownRef.current[keyToday]) {
      showLocalNotification("RT30X6 – Møde i aften!", `${m.title} kl. ${m.time} på ${m.location}`);
      shownRef.current[keyToday] = true;
      localStorage.setItem(keyToday, "1");
    }
    // Deadline tomorrow
    if (m.deadline) {
      const dlDate = new Date(m.deadline);
      const dlDays = Math.ceil((dlDate - now) / 86400000);
      if (dlDays === 1 && !shownRef.current[keyDl]) {
        showLocalNotification("RT30X6 – Husk tilmelding!", `Frist i morgen for ${m.title}`);
        shownRef.current[keyDl] = true;
        localStorage.setItem(keyDl, "1");
      }
    }
  }
}

