const FinesOverview = ({ members, meetings }) => {
  const cyMeetings = meetings.filter(m => isPast(m.date) && new Date(m.date) >= CY_START);
  const memberFines = members.map(member => {
    const total = cyMeetings.reduce((sum, mtg) => {
      return sum + (mtg.fines || []).filter(f => f.memberId === member.id && f.amount).reduce((s, f) => s + (parseFloat(f.amount) || 0), 0);
    }, 0);
    const details = cyMeetings.flatMap(mtg =>
      (mtg.fines || []).filter(f => f.memberId === member.id && f.amount).map(f => ({ ...f, meetingTitle: mtg.title, meetingDate: mtg.date }))
    );
    return { member, total, details };
  }).filter(x => x.total > 0).sort((a, b) => b.total - a.total);

  const grandTotal = memberFines.reduce((s, x) => s + x.total, 0);

  return (
    <div>
      <div style={{ marginBottom: 28 }}>
        <h1 style={{ margin: "0 0 4px", fontFamily: "Outfit", fontSize: 36, fontWeight: 900, color: C.white }}>Bøder</h1>
        <div style={{ fontSize: 14, color: C.soft }}>
          Klubår: 1. maj {CY_START.getFullYear()} – 30. april {CY_START.getFullYear()+1} · Total: <span style={{ color: C.gold, fontWeight: 700 }}>{grandTotal} kr</span>
        </div>
      </div>
      {memberFines.length === 0 ? (
        <div style={{ color: C.faint, fontSize: 16, textAlign: "center", marginTop: 60 }}>Ingen bøder dette klubår 🎉</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
          {memberFines.map(({ member, total, details }) => (
            <FineRow key={member.id} member={member} total={total} details={details} />
          ))}
        </div>
      )}
    </div>
  );
};

